#!/usr/bin/env node
// cratylus-shim: eventTap
// THIN SHIM — projected by canon for a skill declaring runtime:{capability:'eventTap'}.
// Forwards to the host-installed `cratylus` CLI (installed per host, never bundled).
// NOT a bundle of the capability impl — the impl lives host-side behind the runtime
// port, addressed by the CLI, never imported here. Zero cross-package imports.
import { spawnSync } from 'node:child_process';
const r = spawnSync('cratylus', ['eventTap', ...process.argv.slice(2)], {
  stdio: 'inherit',
});
process.exit(r.status ?? 1);

