const AGENT_FLAG = "agent";
// Where the launched agent is published for the session module, which omp never answers `--agent`.
const LAUNCHED_AGENT = Symbol.for("cratylus.launched-agent");
// The judge the session module lends, and what a launch that has not read back is held to.
const JUDGE = Symbol.for("cratylus.judge");
type Judge = (ctx: unknown, prompt: string, act: string, field: string) => Promise<{ value: boolean; reason: string } | undefined>;
const READBACK_PROMPT = "You judge whether an agent has given the operator its readback, for one drift tell: acting before reading back.\n\nYou are given everything the agent has told the operator in visible text this session. The readback tells the operator the current design of the bounded contexts the work touches, their open decisions, and the cuts in flight, saying so plainly where there are none. A promise to read back, a plan or a summary of the request is not a readback. The readback names each open decision as open, and it may go on to say the agent is settling it now. Stating an open decision as already settled, or leaving it out, is not a readback of it. Text after a readback has been given, including the agent's own decisions, never undoes that readback.\n\nAnswer with exactly one JSON object and nothing else:\n{\"given\": <true or false>, \"reason\": \"<one sentence: what the readback covers, or what it lacks>\"}";
const READBACK_REFUSAL = "reconstitution: give the operator the readback (current design, open decisions, cuts in flight) in visible text before this act, then make this call again in the same turn.";
const READBACK_UNSEEN_REFUSAL = "reconstitution: give the operator the readback (current design, open decisions, cuts in flight) as the text of your reply. The operator has seen no text from you yet, and your thinking is not visible to the operator. Write the readback as reply text, then make this call again in the same turn.";
// What an agent dispatching a delegate from `eval` code is refused with, and that code.
const EVAL_DISPATCH_REFUSAL = "dispatch: dispatch a delegate with the task tool, where its assignment is checked.";
const EVAL_DISPATCH = /(?<![\w.$])(?:agent|workpool)\s*\(|(?<![\w.$])tool\s*(?:\??\.\s*task\b|\[\s*["'`]task["'`]\s*\])/;
// The tools whose call changes something whatever its input: a dispatch, a file written or
// edited (a write to `agent://` messages a running agent).
const CHANGING_TOOLS: readonly string[] = ["task", "write", "edit", "ast_edit"];
const AGENT_STATUS = "cratylus-agent";
// omp exports no module path to its advisor settings; its settings registry holds the handle.
const ADVISOR_ENABLED = lookup("advisor.enabled") as Overridable<boolean>;

interface Parameter {
  name: string;
  description: string;
  required: boolean;
  schema: Record<string, unknown>;
  positional?: true;
}
interface Verb {
  name: string;
  concept: string;
  purpose: string;
  when: string;
  effect: "reads" | "appends";
  parameters: Parameter[];
}
interface Explanation {
  name: string;
  purpose: string;
  when: string;
  verbs: Verb[];
}

// A program's output; its own message, when it refuses.
function execOf(file: string, args: string[], cwd?: string, signal?: AbortSignal): Promise<string> {
  const { promise, resolve, reject } = Promise.withResolvers<string>();
  execFile(file, args, { cwd, signal, maxBuffer: 64 * 1024 * 1024 }, (error, stdout, stderr) => {
    if (error) reject(new Error(String(stderr).trim() || String(stdout).trim() || error.message));
    else resolve(String(stdout));
  });
  return promise;
}
// The installed command's output; its own message, when it refuses.
const run = (args: string[], cwd?: string, signal?: AbortSignal): Promise<string> => execOf(COMMAND, args, cwd, signal);

const requirement = (p: Parameter): string => (p.required ? "required" : "optional");

function description(e: Explanation): string {
  return [
    e.purpose,
    `When: ${e.when}`,
    ...e.verbs.map((v) =>
      [
        `Verb ${v.name} (concept: ${v.concept}; ${v.effect})`,
        `Purpose: ${v.purpose}`,
        `When: ${v.when}`,
        ...v.parameters.map((p) => `Parameter ${p.name} (${requirement(p)}): ${p.description}`),
      ].join("\n"),
    ),
  ].join("\n\n");
}

// A required `verb`, then each parameter once, with what each verb says of it and its
// schema: the one schema every verb declares, or each distinct one under `anyOf`.
function parameters(e: Explanation): Record<string, unknown> {
  const properties: Record<string, Record<string, unknown>> = {
    verb: {
      type: "string",
      enum: e.verbs.map((v) => v.name),
      description: e.verbs.map((v) => `${v.name} (${v.effect})`).join("; "),
    },
  };
  const said = new Map<string, { schemas: Map<string, Record<string, unknown>>; lines: string[] }>();
  for (const v of e.verbs)
    for (const p of v.parameters) {
      const entry = said.get(p.name) ?? { schemas: new Map(), lines: [] };
      entry.schemas.set(JSON.stringify(p.schema), p.schema);
      entry.lines.push(`${v.name} (${requirement(p)}): ${p.description}`);
      said.set(p.name, entry);
    }
  for (const [name, { schemas, lines }] of said) {
    const distinct = [...schemas.values()];
    properties[name] = {
      ...(distinct.length === 1 ? distinct[0] : { anyOf: distinct }),
      description: lines.join("\n"),
    };
  }
  return { type: "object", properties, required: ["verb"] };
}

// The command line of one call: the verb, its positional, then each flag given as one
// `--flag=value` token, so a value led by `-` is never read as a flag. A positional led by
// `-` is one the command cannot take literally; it goes as a flag-shaped token of its own
// (`=` appended where it has none), which the command refuses in its own words and never
// reads as a request for its help or its explanation.
function argv(capability: string, verb: Verb | undefined, args: Record<string, unknown>): string[] {
  const positional = verb?.parameters.find((p) => p.positional === true)?.name;
  const words = [capability, String(args.verb)];
  if (positional !== undefined && args[positional] != null) {
    const word = String(args[positional]);
    words.push(word.startsWith("-") && word !== "-" && !word.includes("=") ? `${word}=` : word);
